import os
from typing import Optional, Tuple

import boto3
from botocore.exceptions import BotoCoreError, ClientError


def _kms_client():
    region = os.getenv("AWS_REGION") or os.getenv("AWS_DEFAULT_REGION")
    if region:
        return boto3.client("kms", region_name=region)
    return boto3.client("kms")


def generate_data_key(
    key_id: str,
    key_spec: str = "AES_256",
    encryption_context: Optional[dict] = None,
) -> Tuple[bytes, bytes]:
    """
    Generate a plaintext data key and a KMS-encrypted copy for envelope encryption.
    Returns: (plaintext_data_key, encrypted_data_key)
    """
    client = _kms_client()
    params = {"KeyId": key_id, "KeySpec": key_spec}
    if encryption_context:
        params["EncryptionContext"] = encryption_context

    try:
        response = client.generate_data_key(**params)
        return response["Plaintext"], response["CiphertextBlob"]
    except (ClientError, BotoCoreError) as e:
        raise RuntimeError(f"Failed to generate data key via AWS KMS: {e}") from e


def encrypt_envelope(
    key_id: str,
    plaintext: bytes,
    encryption_context: Optional[dict] = None,
) -> dict:
    """
    Envelope encrypt `plaintext` with a KMS-generated data key.
    Returns a package containing:
      - encrypted_data_key: KMS-wrapped data key
      - iv: AES-GCM IV
      - ciphertext: encrypted payload
      - tag: AES-GCM authentication tag
    """
    try:
        from cryptography.hazmat.primitives.ciphers.aead import AESGCM
    except ImportError as e:
        raise ImportError(
            "cryptography is required for local data encryption: pip install cryptography"
        ) from e

    data_key, encrypted_data_key = generate_data_key(
        key_id=key_id,
        key_spec="AES_256",
        encryption_context=encryption_context,
    )

    aesgcm = AESGCM(data_key)
    iv = os.urandom(12)
    aad = None
    if encryption_context:
        aad = _serialize_encryption_context(encryption_context)

    ciphertext_with_tag = aesgcm.encrypt(iv, plaintext, aad)

    # AESGCM returns ciphertext || tag
    ciphertext = ciphertext_with_tag[:-16]
    tag = ciphertext_with_tag[-16:]

    return {
        "encrypted_data_key": encrypted_data_key,
        "iv": iv,
        "ciphertext": ciphertext,
        "tag": tag,
    }


def decrypt_envelope(
    key_id: str,
    encrypted_data_key: bytes,
    iv: bytes,
    ciphertext: bytes,
    tag: bytes,
    encryption_context: Optional[dict] = None,
) -> bytes:
    """
    Decrypt an envelope-encrypted package created by encrypt_envelope.
    """
    try:
        from cryptography.hazmat.primitives.ciphers.aead import AESGCM
    except ImportError as e:
        raise ImportError(
            "cryptography is required for local data decryption: pip install cryptography"
        ) from e

    client = _kms_client()
    params = {"CiphertextBlob": encrypted_data_key, "KeyId": key_id}
    if encryption_context:
        params["EncryptionContext"] = encryption_context

    try:
        response = client.decrypt(**params)
        data_key = response["Plaintext"]
    except (ClientError, BotoCoreError) as e:
        raise RuntimeError(f"Failed to decrypt data key via AWS KMS: {e}") from e

    aad = None
    if encryption_context:
        aad = _serialize_encryption_context(encryption_context)

    aesgcm = AESGCM(data_key)
    return aesgcm.decrypt(iv, ciphertext + tag, aad)


def _serialize_encryption_context(encryption_context: dict) -> bytes:
    items = sorted((str(k), str(v)) for k, v in encryption_context.items())
    return "\n".join(f"{k}={v}" for k, v in items).encode("utf-8")
